ALTER TABLE public.gallery_shares ADD COLUMN IF NOT EXISTS category_id uuid REFERENCES public.product_categories(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS is_category_scoped boolean NOT NULL DEFAULT false;
ALTER POLICY "gallery objects read" ON storage.objects TO authenticated USING (bucket_id='gallery' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.gallery_images gi WHERE gi.image_url=name AND public.has_perm(auth.uid(),'gallery','read'))));
DO $$ DECLARE t text; m text; BEGIN FOR t,m IN SELECT * FROM (VALUES ('clients','clients'),('employees','employees'),('orders','orders'),('projects','projects'),('products','catalog'),('product_categories','catalog'),('gallery_images','gallery'),('gallery_shares','gallery')) v(t,m) LOOP EXECUTE format('CREATE POLICY "enforce module permissions" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.has_perm(auth.uid(), %L, CASE current_setting(''request.method'', true) WHEN ''DELETE'' THEN ''delete'' WHEN ''PATCH'' THEN ''update'' ELSE ''read'' END)) WITH CHECK (public.has_perm(auth.uid(), %L, CASE current_setting(''request.method'', true) WHEN ''POST'' THEN ''create'' ELSE ''update'' END))',t,m,m); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.preserve_last_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.role='admin' AND (TG_OP='DELETE' OR NEW.role<>'admin') THEN PERFORM pg_advisory_xact_lock(8241963); IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='admin' AND id<>OLD.id) THEN RAISE EXCEPTION 'No puedes quitar el último administrador'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.preserve_last_admin() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER preserve_last_admin BEFORE DELETE OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.preserve_last_admin();